proof.raw_tex:
\begin{prop}\label{prop:main-conv}%
	Let the filtration $\mathcal{F}^k = \cup_{i=1}^k \mathcal{X}^i$ be given by the state $\mathcal{X}^k = \{x^k,y^k,I^{k-1},U_1^{k-1},\dots,U_n^{k-1}\}$.
	If \Cref{ass:strong-ass} holds, the iterates of \Cref{alg:pvrsg} satisfy
	\begin{equation}\label{eq:prop-lyapunov-bound}
		\Exp \big[ \norm{x^{k+1} - x^\star}^2 + \sum_{i=1}^n \widehat{\gamma}_i\norm{y_i^{k+1} - y_i^\star}^2 \big| \mathcal{F}^k \big] \leq  \mathcal{P}(x^k) + \mathcal{D}(y^k),
	\end{equation}
	where $x^\star$ is the unique solution of \Cref{eq:problem} and $y_i^\star = \nabla f_i(x^\star)$.
	See \Cref{def:lyap-terms} for $\mathcal{P}$, $\mathcal{D}$, and $\mathcal{V}$.

	If the primal updates satisfy
	\begin{align}\label{eq:prim-contract}
		\mathcal{P}(x^k) \leq (1-\rho_P)\norm{x^k - x^\star}^2
	\end{align}
	and the dual updates satisfy
	\begin{align}\label{eq:dual-contract}
		\mathcal{D}(y^k) \leq (1-\rho_D)\sum_{i=1}^n \widehat{\gamma}_i\norm{y_i^k - y_i^\star}^2
	\end{align}
	with $\rho_P, \rho_D \in (0,1]$ then \Cref{alg:pvrsg} converges linearly according to
	\begin{align*}
		\Exp \big[ \norm{x^{k} - x^\star}^2 + \sum_{i=1}^n \widehat{\gamma}_i\norm{y_i^{k} - y_i^\star}^2 \big] \in \mathcal{O}((1 - \min(\rho_P, \rho_D))^k).
	\end{align*}
	\begin{proof}
		See \Cref{sec:proof-prop-lemma}.
	\end{proof}
\end{prop}

\begin{lem}[Primal Contraction]\label{lem:prim-contract}%
	Let \Cref{ass:strong-ass} hold, the primal iterates of \Cref{alg:pvrsg} satisfy the primal contraction \Cref{eq:prim-contract} with
	\begin{align*}
		\rho_P = \mu\lambda(2 - \nu\lambda)
	\end{align*}
	where $\nu = \max_i {\textstyle  (1+\delta^{-1})\frac{L_i\eta_i\gamma_i}{n p_i}  +  (1+\delta)\frac{L_i}{n p_i} - \delta\mu}$.
	\begin{proof}
		See \Cref{sec:proof-prop-lemma}.
	\end{proof}
\end{lem}

\begin{lem}[Dual Contraction]\label{lem:dual-contract}%
	Let \Cref{ass:strong-ass} and $\gamma_i > 0$ hold for all $i \in\{1,\dots,n\}$, the dual iterates of \Cref{alg:pvrsg} satisfy the dual contraction \Cref{eq:dual-contract} with
	\begin{align*}
		\rho_D = \min_i {\textstyle \eta_i - \tfrac{1}{\gamma_i}}.
	\end{align*}
	\begin{proof}
		See \Cref{sec:proof-prop-lemma}.
	\end{proof}
\end{lem}

\begin{lem}\label{lem:sampled-lipschitz}%
	Let $L_i$ and $\mu$ be from \Cref{ass:strong-ass} and $p_i$ from \Cref{alg:pvrsg}, then $\max_i \frac{L_i}{np_i} \geq \mu$.
	Furthermore, if $\max_i \frac{L_i}{np_i} = \mu$ then $\frac{L_i}{np_i} = \mu$ for all $i \in \{1,\dots,n\}$.
	\begin{proof}
		See \Cref{sec:proof-prop-lemma}.
	\end{proof}
\end{lem}

\begin{proof}
		See \Cref{sec:proof-theorems}.
	\end{proof}

\begin{proof}[\textbf{Proof of \Cref{prop:main-conv}}]%
	Let $x^\star$ be the unique solution to \Cref{eq:problem}.
	With $g$ being proper, closed and convex, the primal updates satisfy
	\begin{equation}\label{eq:prim-update-lyap}
		\begin{aligned}
			&\Exp[\norm{x^{k+1} - x^\star}^2|\mathcal{F}^k] \\
			&\quad= \Exp[\norm{\prox_{\lambda g}(z^{k+1}) - \prox_{\lambda g}(x^\star - \lambda \nabla F(x^\star))}^2|\mathcal{F}^k] \\
			&\quad\leq
			%\Exp[\norm{z^{k+1} - (x^\star - \lambda \nabla F(x^\star))}^2|\mathcal{F}^k] \\
			%&\quad=
			\Exp[\norm{x^k - \tfrac{\lambda}{n}\big(\tfrac{1}{p_{I^k}}(\nabla f_{I^k}(x^k) - y_{I^k}^k) + \textstyle\sum_{i=1}^n y_i^k\big) - x^\star + \lambda \nabla F(x^\star)}^2|\mathcal{F}^k] \\
			&\quad= \norm{(x^k - \lambda \nabla F(x^k)) - (x^\star - \lambda \nabla F(x^\star))}^2\\
		&\quad\quad + \lambda^2 \Exp\big[\norm[\big]{\big(\tfrac{1}{n p_{I^k}} \nabla f_{I^k}(x^k) - \nabla F(x^k)\big) - \big(\tfrac{1}{n p_{I^k}}y_{I^k}^k - {\textstyle\frac{1}{n}\sum_{i=1}^n} y_i^k \big)}^2|\mathcal{F}^k\big] \\
		&\quad= \norm{x^k - x^\star}^2 - 2\lambda\inprod{\nabla F(x^k) - \nabla F(x^\star)}{x^k-x^\star} + \lambda^2\norm{\nabla F(x^k) -\nabla F(x^\star)}^2\\
	&\quad\quad + \lambda^2 \Exp\big[\norm[\big]{\big(\tfrac{1}{n p_{I^k}} \nabla f_{I^k}(x^k) - \nabla F(x^k)\big) - \big(\tfrac{1}{n p_{I^k}}y_{I^k}^k - {\textstyle\frac{1}{n}\sum_{i=1}^n} y_i^k \big)}^2|\mathcal{F}^k\big].
\end{aligned}
\end{equation}
The first equality is given by the solution being a fixed point to the proximal-gradient update $x^\star = \prox_{\lambda g}(x^\star - \lambda \nabla F(x^\star))$ \cite[Corollary 28.9]{bauschke_convex_2017}.
The first inequality is due to the non-expansiveness of $\prox_{\lambda g}$.
The second to last equality is given by $\Exp\norm{X}^2 =\norm{\Exp X}^2 + \Exp\norm{X - \Exp X}^2$ where $X$ is a random variable.

The last term in \Cref{eq:prim-update-lyap} satisfies the following upper bound for all $\delta > 0$:
\begin{equation}\label{eq:update-variance-bound}
	\begin{aligned}
		&\Exp[\norm{(\tfrac{1}{n p_{I^k}} \nabla f_{I^k}(x^k) - \nabla F(x^k)) - (\tfrac{1}{n p_{I^k}}y_{I^k}^k - {\textstyle\frac{1}{n}\sum_{i=1}^n} y_i^k )}^2|\mathcal{F}^k]\\
		&\quad\begin{aligned}
			= \Exp[\| &\tfrac{1}{np_{I^k}}(\nabla f_{I^k}(x^k) - \nabla f_{I^k}(x^\star)) - (\nabla F(x^k) - \nabla F(x^\star))\\
			&- \tfrac{1}{np_{I^k}}(y_{I^k}^k - y_{I^k}^\star) + {\textstyle\frac{1}{n}\sum_{i=1}^n}(y_i^k - y_i^\star) \|^2 |\mathcal{F}^k]
		\end{aligned} \\
		&\quad\leq (1+\delta)\Exp[\norm{ \tfrac{1}{np_{I^k}}(\nabla f_{I^k}(x^k) - \nabla f_{I^k}(x^\star)) - (\nabla F(x^k) - \nabla F(x^\star)) }^2 |\mathcal{F}^k]\\
		&\quad\quad + (1+\delta^{-1})\Exp[\norm{\tfrac{1}{np_{I^k}}(y_{I^k}^k - y_{I^k}^\star) - {\textstyle\frac{1}{n}\sum_{i=1}^n}(y_i^k - y_i^\star)}^2 |\mathcal{F}^k]\\
		&\quad= (1+\delta)\big(\Exp[\norm{\tfrac{1}{np_{I^k}}(\nabla f_{I^k}(x^k) - \nabla f_{I^k}(x^\star))}^2|\mathcal{F}^k] - \norm{\nabla F(x^k) - \nabla F(x^\star)}^2\big) \\
		&\quad\quad + (1+\delta^{-1})\big(\Exp[\norm{\tfrac{1}{np_{I^k}}(y_{I^k}^k - y_{I^k}^\star)}^2|\mathcal{F}^k] - \norm{{\textstyle\frac{1}{n}\sum_{i=1}^n}(y_i^k - y_i^\star)}^2\big) \\
		&\quad= (1+\delta){\textstyle\sum\frac{1}{n^2 p_i}}\norm{\nabla f_i(x^k) - \nabla f_i(x^\star)}^2 - (1+\delta)\norm{\nabla F(x^k) - \nabla F(x^\star)}^2 \\
		&\quad\quad + (1+\delta^{-1}){\textstyle\sum\frac{1}{n^2 p_i}}\norm{y_i^k - y_i^\star}^2 - (1+\delta^{-1})\norm{{\textstyle\frac{1}{n}\sum_{i=1}^n}(y_i^k - y_i^\star)}^2.
	\end{aligned}
\end{equation}
The inequality is given by Young's inequality, the second to last equality is given by $\Exp\norm{X - \Exp X}^2 = \Exp\norm{X}^2-\norm{\Exp X}^2$ where $X$ is a random variable.

The dual updates satisfy
\begin{align*}
	\norm{y_i^{k+1} - y_i^\star}^2
	&= \norm{y_i^k + U_i^k(\nabla f_i(x^k) - y_i^k) - y_i^\star}^2 \\
	&= (1- U_i^k)\norm{y_i^k - y_i^\star}^2 + U_i^k\norm{\nabla f_i(x^k) - \nabla f_i(x^\star)}^2
\end{align*}
since $U_i^k \in \{0,1\}$.
Summing over all terms, taking expected value and using linearity of the expected value give
\begin{equation}\label{eq:dual-update-lyap}
	\begin{aligned}
		\Exp[{\textstyle\sum_{i=1}^n} \widehat{\gamma}_i\norm{y_i^{k+1} - y_i^\star}^2|\mathcal{F}^k]
		&= {\textstyle\sum_{i=1}^n} (1-\eta_i)\widehat{\gamma}_i\norm{y^k - y^\star}^2 \\
		&\quad + {\textstyle\sum_{i=1}^n}{\eta_i \widehat{\gamma}_i}\norm{\nabla f_i(x^k) - \nabla f_i(x^\star)}^2.
	\end{aligned}
\end{equation}
Adding \Cref{eq:dual-update-lyap} to \Cref{eq:prim-update-lyap} and substituting in \Cref{eq:update-variance-bound} and using the definition $\frac{\gamma_i}{\gamma_i} = 1$ when $\gamma_i = 0$ then yield \Cref{eq:prop-lyapunov-bound}.
Applying \Cref{eq:prim-contract} and \Cref{eq:dual-contract}, using the law of total expectation and telescoping the inequalities give the stated rate.
\end{proof}

\begin{proof}[\textbf{Proof of \Cref{lem:prim-contract}}]%
	First note that $\mu$-strong monotonicity and the Cauchy--Schwarz inequality imply
	\begin{equation}\label{eq:reverse-lipschitz}
		\norm{\nabla F(x^k) - \nabla F(x^\star)} \geq \mu \norm{x^k - x^\star}.
	\end{equation}
	Consider the terms of $\mathcal{V}(x^k)$.
	Using \Cref{eq:reverse-lipschitz} and Cauchy--Schwarz in the last term yield
	\begin{align*}
		\norm{\nabla F(x^k) - \nabla F(x^\star)}^2
		&\geq \mu\norm{\nabla F(x^k) - \nabla F(x^\star)}\norm{x^k - x^\star} \\
		&\geq \mu\inprod{\nabla F(x^k) - \nabla F(x^\star)}{x^k - x^\star}.
	\end{align*}
	Using $\frac{1}{L_i}$-cocoercivity of $\nabla f_i$ in the first term of $\mathcal{V}(x^k)$ yields
	\begin{align*}
		\sum_{i=1}^n & {\textstyle (\frac{\eta_i\gamma_i}{\delta}  + 1)\frac{1}{n^2 p_i} }\norm{\nabla f_i(x^k) - \nabla f_i(x^\star)}^2 \\
		&\leq \sum_{i=1}^n {\textstyle (\frac{\eta_i\gamma_i}{\delta}  + 1)\frac{L_i}{n^2 p_i} } \inprod{\nabla f_i(x^k) - \nabla f_i(x^\star)}{x^k - x^\star} \\
		&\leq \max_i({\textstyle(\frac{\eta_i\gamma_i}{\delta}  + 1)\frac{L_i}{n p_i}}) \inprod{\nabla F(x^k) - \nabla F(x^\star)}{x^k - x^\star}.
	\end{align*}
	Adding the terms back together yields
	\begin{align*}
		\mathcal{V}(x^k)
		&\leq \lambda^2 \nu \inprod{\nabla F(x^k) - \nabla F(x^\star)}{x^k - x^\star}
	\end{align*}
	where $\nu = \max_i(  (1+\delta^{-1})\frac{L_i\eta_i\gamma_i}{n p_i}  +  (1+\delta)\frac{L_i}{n p_i} - \delta\mu)$.
	This can now be summarized as
	\begin{align*}
		\mathcal{P}(x^k)
		&\leq \norm{x^k - x^\star}^2  - \lambda\big(2 - \nu\lambda \big) \inprod{\nabla F(x^k) - \nabla F (x^\star)}{x^k - x^\star} \\
		&\leq \norm{x^k - x^\star}^2  - \mu\lambda\big(2 - \nu\lambda \big) \norm{x^k - x^\star}^2 \\
		&= (1 - \rho_P)\norm{x^k - x^\star}^2,
	\end{align*}
	where $\rho_P = \mu\lambda(2 - \nu\lambda)$ and the last inequality is given by the strong monotonicity of $\nabla F$.
\end{proof}

\begin{proof}[\textbf{Proof of \Cref{lem:dual-contract}}]%
	Since norms are non-negative, we have
	\begin{align*}
		\mathcal{D}(y^k)
		\leq \sum_{i=1}^n {\textstyle(1 - \eta_i  + \frac{1}{\gamma_i})\widehat{\gamma}_i} \norm{y_i^k - y_i^\star}^2
		\leq (1 - \rho_D)\sum_{i=1}^n \widehat{\gamma}_i \norm{y_i^k - y_i^\star}^2,
	\end{align*}
	where $\rho_D = \min_i(\eta_i - \tfrac{1}{\gamma_i})$.
\end{proof}

\begin{proof}[\textbf{Proof of \Cref{lem:sampled-lipschitz}}]%
	An $L$-smooth and $\mu$-strongly convex function must satisfy $L \geq \mu$.
	Assuming $\max_i(\frac{L_i}{np_i}) < \mu$ yields the following contradiction
	\begin{align*}
		\mu > \max_i \tfrac{L_i}{np_i} = \sum_{j=1}^n  p_j \max_i \tfrac{L_i}{np_i} \geq \sum_{j=1}^n  p_j \tfrac{L_j}{np_j} = \sum_{i=1}^n \tfrac{L_i}{n} \geq L.
	\end{align*}
	If $\max_i(\frac{L_i}{np_i}) = \mu$, equality must hold everywhere and we have
	\begin{align*}
		0 = \sum_{j=1}^n  p_j \max_i \tfrac{L_i}{np_i} - \sum_{j=1}^n  p_j \tfrac{L_j}{np_j} = \sum_{j=1}^n  p_j (\max_i \tfrac{L_i}{np_i} - \tfrac{L_j}{np_j}).
	\end{align*}
	Since $p_j > 0$ and $\max_i \tfrac{L_i}{np_i} - \tfrac{L_j}{np_j} \geq 0$, we have $\max_i \tfrac{L_i}{np_i} = \tfrac{L_j}{np_j}$ for all $j\in\{1,\dots,n\}$.
\end{proof}

\begin{proof}[\textbf{Proof of \Cref{thm:pvrsg-conv}}]%
	Application of \Cref{lem:prim-contract} and \ref{lem:dual-contract} in \Cref{prop:main-conv} yields the convergence rate
	\begin{align*}
		\Exp \Big[ \norm{x^{k} - x^\star}^2 + \sum_{i=1}^n \widehat{\gamma}_i\norm{y_i^{k} - y_i^\star}^2 \Big] \in \mathcal{O}((1 - \min(\rho_P, \rho_D))^k)
	\end{align*}
	with
	\begin{align*}
		\rho_P &= \mu\lambda(2- \nu\lambda) \\
		\rho_D &= \min_i \eta_i - \tfrac{1}{\gamma_i} \\
		\nu &= \max_i  {\textstyle(1+\delta^{-1})\frac{L_i\eta_i\gamma_i}{n p_i}  +  (1+\delta)\frac{L_i}{n p_i} - \delta\mu},
	\end{align*}
	which hold for all choices of $\delta > 0$ and $\gamma_i > 0$ for all $i\in\{1,\dots,n\}$.
	If there exists $\delta$ and $\gamma_1,\dots,\gamma_n$ such that $\min(\rho_P,\rho_D) \in (0,1]$ we have convergence.
	We restrict ourselves to only search for $\delta$ and $\gamma_1,\dots,\gamma_n$ such that $\rho_P = \rho_D = \rho$ for some $\rho \in (0,1]$.
	For all $i\in\{1,\dots,n\}$, select $\gamma_i = \frac{1}{\eta_i - \rho}$, which is positive when $\rho < \eta_i$, and convergence is then proved if there exists $\rho \in (0,\min_i \eta_i)$ and $\delta > 0$ such that
	\begin{align*}
		\rho &= \mu\lambda(2 - \nu\lambda )\\
		\nu &= \max_i {\textstyle(1+\delta^{-1})\frac{L_i}{n p_i}\frac{\eta_i}{\eta_i - \rho}  +  (1+\delta)\frac{L_i}{n p_i} - \delta\mu}.
	\end{align*}
	The variable $\nu$ can be minimized w.r.t. $\delta$ if $\max_i \frac{L_i}{np_i} > \mu$.
	The minimum then exists and is unique since $\nu$ as a function of $\delta$ is continuous, strictly convex, and $\nu\to\infty$ both when $\delta \to 0^+$ and $\delta \to \infty$.
	Calling the minimum point $\delta^\star$, noting that $\delta^\star > 0$, and inserting it and the choice of $\gamma_i$ in the expression for $\widehat{\gamma}_i$ from \Cref{def:lyap-terms} yield the first statement of the theorem.

	When $\max_i \frac{L_i}{np_i} \not> \mu$, \Cref{lem:sampled-lipschitz} gives $\frac{L_i}{n p_i} = \mu$ for all $i\in\{1,\dots,n\}$ and
	\begin{align*}
		\nu = \mu + \mu(1+\delta^{-1})\max_i \tfrac{\eta_i}{\eta_i-\rho}.
	\end{align*}
	This can not be minimized w.r.t. $\delta$ since the $\inf$ is not attained.
	However, any $\delta>0$ will yield a valid $\rho$ and $\widehat{\gamma}_i$, giving the rate
	\begin{align*}
		&\Exp \Big[ \norm{x^{k} - x^\star}^2 + \sum_{i=1}^n{\textstyle \frac{ \lambda^2}{n^2p_i} \frac{1}{\eta_i - \rho}} \norm{y_i^{k} - y_i^\star}^2 \Big] \\
		&\quad \leq \Exp \Big[ \norm{x^{k} - x^\star}^2 + \sum_{i=1}^n \widehat{\gamma}_i\norm{y_i^{k} - y_i^\star}^2 \Big]
		\in \mathcal{O}((1 - \rho)^k).
	\end{align*}
	Taking the limit as $\delta \to \infty$ results in the stated interval.
\end{proof}

