We consider the regularized finite sum problem
\begin{align}\label{eq:problem}
	\min_{x \in \R^N} \quad& g(x) + F(x),
\end{align}

\begin{algorithm}[H]%
	\caption{PVRSG - Proximal Variance-Reduced Stochastic Gradient}\label{alg:pvrsg}
	Given the function $g$, the functions $f_1,\dots,f_n$, initial primal and dual points, $x^0$ and $y_1^0,\dots y_n^0$, iteratively perform the following for $k\in\{0,1,\dots\}$.
	\begin{align*}
		&\textbf{Sampling:}
		&&\text{Randomly sample } (I^k,U_1^k,\dots,U_n^k) \text{ from } \{1,\dots,n\}\times\{0,1\}^n.
		\\
		&\textbf{Primal Update:}
		&&\begin{aligned}[t]
			&\begin{aligned}
				z^{k+1} &=x^k - \tfrac{\lambda}{n} \big(\tfrac{1}{p_{I^k}}(\nabla f_{I^k} (x^k) - y_{I^k}^k) + {\textstyle\sum_{i=1}^n} y_i^k\big), \\
				x^{k+1} &= \prox_{\lambda g}(z^{k+1}).
			\end{aligned}
		\end{aligned}\\
		\\
		&\textbf{Dual Update:}
		&&\begin{aligned}[t]
			&\begin{aligned}
				y_i^{k+1} &= y_i^k + U_i^k(\nabla f_i (x^k) - y_i^k), \quad \forall i \in \{1,\dots,n\}.
			\end{aligned}
		\end{aligned}
	\end{align*}
	The sampling distributions of $(I^k,U_1^k,\dots,U_n^k)$ for all $k\in\{0,1,\dots\}$ are the same and independent.
	Furthermore, the distribution is such that $P(I^k = i) = p_i > 0$ and the expected update frequency $\eta_i > 0$, see \Cref{def:update-freq}, for all $i\in\{1,\dots,n\}$.
	The step-size satisfies $\lambda > 0$.
\end{algorithm}

\begin{defin}[Expected Update Frequency]\label{def:update-freq}%
	Let $U_1^k,\dots,U_n^k$ be given by the sampling in \Cref{alg:pvrsg}.
	The expected update frequency of the $i$th dual variable is
	\begin{align*}
		\eta_i = \Exp[U_i^k|\mathcal{F}^k],
	\end{align*}
	where $\mathcal{F}^k = \cup_{i=1}^k \mathcal{X}^i$ and $\mathcal{X}^k = \{x^k,y^k,I^{k-1},U_1^{k-1},\dots,U_n^{k-1}\}$.
\end{defin}

A convex function $f: \R^d 	o \R$ is \emph{$L$-smooth} with $L > 0$ if it is differentiable and its gradient is $	frac{1}{L}$-cocoercive, i.e.,
 egin{align*}
	\inprod{
abla f(x) - 
abla f(y)}{x-y} \geq 	frac{1}{L} 
orm{
abla f(x) - 
abla f(y)}^2, \quad  orall x,y \in \R^d.
\end{align*}
Note that the definition of smoothness implies \emph{$L$-Lipschitz continuity} of the gradient $
abla f$.
In fact, for convex $f$, Lipschitz continuity and cocoercivity of $
abla f$ are equivalent \cite[Corollary 18.17]{bauschke_convex_2017}.
A proper function $f: \R^d 	o \R \cup \{\infty\}$ is \emph{$\mu$-strongly convex} with $\mu > 0$ if $f -  rac{\mu}{2}
orm{\cdot}^2$ is convex.

The subdifferential of a $\mu$-strongly convex function is $\mu$-strongly monotone \cite[Example 22.4]{bauschke_convex_2017}, i.e.,
\begin{align*}
	\inprod{u - v}{x-y} \geq \mu \norm{x-y}^2
\end{align*}
holds $\forall x,y \in \mathop{\mathrm{dom}} \partial f$ and $\forall u\in \partial f(x), \forall v \in \partial f(y)$.
A closed, proper and strongly convex function has a unique minimum \cite[Corollary 11.17]{bauschke_convex_2017}.

The \emph{proximal operator} of a closed, convex and proper function $g: \R^d \to \R \cup \{\infty\}$ is defined as
\begin{align*}
	\prox_g(z) = \argmin_x g(x) + \tfrac{1}{2}\norm{x-z}^2.
\end{align*}
Due to strong convexity of $g + \frac{1}{2}\norm{\cdot - z}^2$, the minimum exist and is unique.
Furthermore, the operator $\prox_g$ is \emph{non-expansive}, i.e., Lipschitz continuous with constant $1$ \cite[Proposition 12.28]{bauschke_convex_2017}.

\begin{defin}\label{def:lyap-terms}%
	Let $x^\star$ be the solution to \Cref{eq:problem} and $y_i^\star = \nabla f_i(x^\star)$ for all $i\in\{1,\dots,n\}$.
	With $y = (y_1,\dots,y_n)$, where $y_i \in \R^n$ for $i \in \{1,\dots,n\}$, we define
	\begin{align*}
		\mathcal{P}(x) = \norm{x - x^\star}^2 - 2\lambda\inprod{\nabla F(x) - \nabla F (x^\star)}{x - x^\star} + \lambda^2\mathcal{V}(x)
	\end{align*}
	and
	\begin{align*}
		\mathcal{D}(y)
		&= \sum_{i=1}^n {\textstyle(1 - \eta_i  + \frac{1}{\gamma_i})\widehat{\gamma}_i} \norm{y_i - y_i^\star}^2
		-{\textstyle (1+\delta^{-1})\lambda^2}\norm{{{\textstyle\frac{1}{n}}\sum_{i=1}^n} y_i -  y_i^\star }^2,
	\end{align*}
	where
	\begin{align*}
		\mathcal{V}(x)
		= \sum_{i=1}^n {\textstyle \frac{(1+\delta)}{n^2 p_i}(\frac{\eta_i\gamma_i}{\delta}  + 1) }\norm{\nabla f_i(x) - \nabla f_i(x^\star)}^2 - \delta\norm{\nabla F(x) - \nabla F(x^\star)}^2
	\end{align*}
	with $\gamma_i \geq 0$, $\delta > 0$ and $\widehat{\gamma}_i = \gamma_i \frac{(1+\delta^{-1}) \lambda^2}{n^2p_i}$.
	If $\gamma_i = 0$ we define $\tfrac{\gamma_i}{\gamma_i} := 1$.
\end{defin}

\begin{thm}[PVRSG Convergence]\label{thm:pvrsg-conv}%
	Given $\max_i \frac{L_i}{np_i} > \mu$ and \Cref{ass:strong-ass}, if there exists $\rho \in (0, \min_i \eta_i)$ such that
	\begin{align*}
		\rho &= \mu\lambda(2 - \nu\lambda )\\
		\nu &= \min_{\delta > 0} \max_i {\textstyle(1+\delta^{-1})\frac{L_i}{n p_i}\frac{\eta_i}{\eta_i - \rho}  +  (1+\delta)\frac{L_i}{n p_i} - \delta\mu},
	\end{align*}
	then the iterates of \Cref{alg:pvrsg} converge according to
	\begin{align*}
		\Exp \Big[ \norm{x^{k} - x^\star}^2 + \sum_{i=1}^n \widehat{\gamma}_i\norm{y_i^{k} - y_i^\star}^2 \Big] \in \mathcal{O}((1 - \rho)^k)
	\end{align*}
	where $\widehat{\gamma}_1,\dots,\widehat{\gamma}_n$ are given by $\widehat{\gamma}_i ={\textstyle \frac{ \lambda^2}{n^2p_i} \frac{1}{\eta_i - \rho}(1 + \frac{1}{\delta^\star})}$ and $\delta^\star$ is the unique minimizer of the minimization problem defining $\nu$.

	If instead $\max_i \frac{L_i}{np_i} = \mu$ then $\nu = \mu + \mu\max_i \tfrac{\eta_i}{\eta_i-\rho}$ and the convergence is such that
	\begin{align*}
		\Exp \Big[ \norm{x^{k} - x^\star}^2 + \sum_{i=1}^n{\textstyle \frac{ \lambda^2}{n^2p_i} \frac{1}{\eta_i - \tilde{\rho}}} \norm{y_i^{k} - y_i^\star}^2 \Big] \in \mathcal{O}((1 - \tilde{\rho})^k)
	\end{align*}
	holds for all $\tilde{\rho} \in (0, \rho)$.

\begin{proof}
		See \Cref{sec:proof-theorems}.
	\end{proof}

\begin{proof}[\textbf{Proof of \Cref{thm:pvrsg-conv}}]%
	Application of \Cref{lem:prim-contract} and \ref{lem:dual-contract} in \Cref{prop:main-conv} yields the convergence rate
	\begin{align*}
		\Exp \Big[ \norm{x^{k} - x^\star}^2 + \sum_{i=1}^n \widehat{\gamma}_i\norm{y_i^{k} - y_i^\star}^2 \Big] \in \mathcal{O}((1 - \min(\rho_P, \rho_D))^k)
	\end{align*}
	with
	\begin{align*}
		\rho_P &= \mu\lambda(2- \nu\lambda) \\
		\rho_D &= \min_i \eta_i - \tfrac{1}{\gamma_i} \\
		\nu &= \max_i  {\textstyle(1+\delta^{-1})\frac{L_i\eta_i\gamma_i}{n p_i}  +  (1+\delta)\frac{L_i}{n p_i} - \delta\mu},
	\end{align*}
	which hold for all choices of $\delta > 0$ and $\gamma_i > 0$ for all $i\in\{1,\dots,n\}$.
	If there exists $\delta$ and $\gamma_1,\dots,\gamma_n$ such that $\min(\rho_P,\rho_D) \in (0,1]$ we have convergence.
	We restrict ourselves to only search for $\delta$ and $\gamma_1,\dots,\gamma_n$ such that $\rho_P = \rho_D = \rho$ for some $\rho \in (0,1]$.
	For all $i\in\{1,\dots,n\}$, select $\gamma_i = \frac{1}{\eta_i - \rho}$, which is positive when $\rho < \eta_i$, and convergence is then proved if there exists $\rho \in (0,\min_i \eta_i)$ and $\delta > 0$ such that
	\begin{align*}
		\rho &= \mu\lambda(2 - \nu\lambda )\\
		\nu &= \max_i {\textstyle(1+\delta^{-1})\frac{L_i}{n p_i}\frac{\eta_i}{\eta_i - \rho}  +  (1+\delta)\frac{L_i}{n p_i} - \delta\mu}.
	\end{align*}
	The variable $\nu$ can be minimized w.r.t. $\delta$ if $\max_i \frac{L_i}{np_i} > \mu$.
	The minimum then exists and is unique since $\nu$ as a function of $\delta$ is continuous, strictly convex, and $\nu\to\infty$ both when $\delta \to 0^+$ and $\delta \to \infty$.
	Calling the minimum point $\delta^\star$, noting that $\delta^\star > 0$, and inserting it and the choice of $\gamma_i$ in the expression for $\widehat{\gamma}_i$ from \Cref{def:lyap-terms} yield the first statement of the theorem.

	When $\max_i \frac{L_i}{np_i} \not> \mu$, \Cref{lem:sampled-lipschitz} gives $\frac{L_i}{n p_i} = \mu$ for all $i\in\{1,\dots,n\}$ and
	\begin{align*}
		\nu = \mu + \mu(1+\delta^{-1})\max_i \tfrac{\eta_i}{\eta_i-\rho}.
	\end{align*}
	This can not be minimized w.r.t. $\delta$ since the $\inf$ is not attained.
	However, any $\delta>0$ will yield a valid $\rho$ and $\widehat{\gamma}_i$, giving the rate
	\begin{align*}
		&\Exp \Big[ \norm{x^{k} - x^\star}^2 + \sum_{i=1}^n{\textstyle \frac{ \lambda^2}{n^2p_i} \frac{1}{\eta_i - \rho}} \norm{y_i^{k} - y_i^\star}^2 \Big] \\
		&\quad \leq \Exp \Big[ \norm{x^{k} - x^\star}^2 + \sum_{i=1}^n \widehat{\gamma}_i\norm{y_i^{k} - y_i^\star}^2 \Big]
		\in \mathcal{O}((1 - \rho)^k).
	\end{align*}
	Taking the limit as $\delta \to \infty$ results in the stated interval.
\end{proof}

Application of \Cref{lem:prim-contract} and \ref{lem:dual-contract} in \Cref{prop:main-conv} yields the convergence rate
\begin{align*}
	\Exp \Big[ \norm{x^{k} - x^\star}^2 + \sum_{i=1}^n \widehat{\gamma}_i\norm{y_i^{k} - y_i^\star}^2 \Big] \in \mathcal{O}((1 - \min(\rho_P, \rho_D))^k)
\end{align*}
with
\begin{align*}
	\rho_P &= \mu\lambda(2- \nu\lambda) \\
	\rho_D &= \min_i \eta_i - \tfrac{1}{\gamma_i} \\
	\nu &= \max_i  {\textstyle(1+\delta^{-1})\frac{L_i\eta_i\gamma_i}{n p_i}  +  (1+\delta)\frac{L_i}{n p_i} - \delta\mu},
\end{align*}
which hold for all choices of $\delta > 0$ and $\gamma_i > 0$ for all $i\in\{1,\dots,n\}$.
If there exists $\delta$ and $\gamma_1,\dots,\gamma_n$ such that $\min(\rho_P,\rho_D) \in (0,1]$ we have convergence.

We restrict ourselves to only search for $\delta$ and $\gamma_1,\dots,\gamma_n$ such that $\rho_P = \rho_D = \rho$ for some $\rho \in (0,1]$.
For all $i\in\{1,\dots,n\}$, select $\gamma_i = \frac{1}{\eta_i - \rho}$, which is positive when $\rho < \eta_i$, and convergence is then proved if there exists $\rho \in (0,\min_i \eta_i)$ and $\delta > 0$ such that
\begin{align*}
	\rho &= \mu\lambda(2 - \nu\lambda )\\
	\nu &= \max_i {\textstyle(1+\delta^{-1})\frac{L_i}{n p_i}\frac{\eta_i}{\eta_i - \rho}  +  (1+\delta)\frac{L_i}{n p_i} - \delta\mu}.
\end{align*}

When $\max_i \frac{L_i}{np_i} \not> \mu$, \Cref{lem:sampled-lipschitz} gives $\frac{L_i}{n p_i} = \mu$ for all $i\in\{1,\dots,n\}$ and
\begin{align*}
	\nu = \mu + \mu(1+\delta^{-1})\max_i \tfrac{\eta_i}{\eta_i-\rho}.
\end{align*}
This can not be minimized w.r.t. $\delta$ since the $\inf$ is not attained.

\begin{prop}\label{prop:main-conv}%
	Let the filtration $\mathcal{F}^k = \cup_{i=1}^k \mathcal{X}^i$ be given by the state $\mathcal{X}^k = \{x^k,y^k,I^{k-1},U_1^{k-1},\dots,U_n^{k-1}\}$.
	If \Cref{ass:strong-ass} holds, the iterates of \Cref{alg:pvrsg} satisfy
	\begin{equation}\label{eq:prop-lyapunov-bound}
		\Exp \big[ \norm{x^{k+1} - x^\star}^2 + \sum_{i=1}^n \widehat{\gamma}_i\norm{y_i^{k+1} - y_i^\star}^2 \big| \mathcal{F}^k \big] \leq  \mathcal{P}(x^k) + \mathcal{D}(y^k),
	\end{equation}
	where $x^\star$ is the unique solution of \Cref{eq:problem} and $y_i^\star = \nabla f_i(x^\star)$.
	See \Cref{def:lyap-terms} for $\mathcal{P}$, $\mathcal{D}$, and $\mathcal{V}$.

	If the primal updates satisfy
	\begin{align}\label{eq:prim-contract}
		\mathcal{P}(x^k) \leq (1-\rho_P)\norm{x^k - x^\star}^2
	\end{align}
	and the dual updates satisfy
	\begin{align}\label{eq:dual-contract}
		\mathcal{D}(y^k) \leq (1-\rho_D)\sum_{i=1}^n \widehat{\gamma}_i\norm{y_i^k - y_i^\star}^2
	\end{align}
	with $\rho_P, \rho_D \in (0,1]$ then \Cref{alg:pvrsg} converges linearly according to
	\begin{align*}
		\Exp \big[ \norm{x^{k} - x^\star}^2 + \sum_{i=1}^n \widehat{\gamma}_i\norm{y_i^{k} - y_i^\star}^2 \big] \in \mathcal{O}((1 - \min(\rho_P, \rho_D))^k).
	\end{align*}

\begin{proof}
		See \Cref{sec:proof-prop-lemma}.
	\end{proof}

The dual updates satisfy
\begin{align*}
	\norm{y_i^{k+1} - y_i^\star}^2
	&= \norm{y_i^k + U_i^k(\nabla f_i(x^k) - y_i^k) - y_i^\star}^2 \\
	&= (1- U_i^k)\norm{y_i^k - y_i^\star}^2 + U_i^k\norm{\nabla f_i(x^k) - \nabla f_i(x^\star)}^2
\end{align*}
since $U_i^k \in \{0,1\}$.
Summing over all terms, taking expected value and using linearity of the expected value give
\begin{equation}\label{eq:dual-update-lyap}
	\begin{aligned}
		\Exp[{\textstyle\sum_{i=1}^n} \widehat{\gamma}_i\norm{y_i^{k+1} - y_i^\star}^2|\mathcal{F}^k]
		&= {\textstyle\sum_{i=1}^n} (1-\eta_i)\widehat{\gamma}_i\norm{y^k - y^\star}^2 \\
		&\quad + {\textstyle\sum_{i=1}^n}{\eta_i \widehat{\gamma}_i}\norm{\nabla f_i(x^k) - \nabla f_i(x^\star)}^2.
	\end{aligned}
\end{equation}

